insert into lq_tpl_topics values (1, $lq$Zahájenie kurzu$lq$, 5, 5, $lq$<p>Rozsah: 5 minút (A aj B). Cieľ: účastníci vedia, prečo sa školenie koná, ako prebieha a ako sa overujú vedomosti.</p><ul><li><p>Predstavenie školiteľa, oprávnenia Keylo s.r.o. a odborného zástupcu.</p></li><li><p>Dôvod školenia: zamestnávateľ je povinný zamestnancov oboznamovať s predpismi a rizikami (§ 7 zákona č. 124/2006 Z. z.) – pri nástupe, pri preradení na inú prácu, pri novej technológii a opakovane najmenej raz za tri roky.</p></li><li><p>Program podľa učebného plánu: vstupné oboznamovanie 4 hodiny, opakované 3 hodiny. Vyučovacia hodina 45 minút, prestávka 5 minút.</p></li><li><p>Oboznamovanie sa koná v pracovnom čase. Účasť sa pri e-learningu potvrdzuje záznamom v aplikácii (čas štúdia každej témy).</p></li><li><p>Záverečné overenie: test s 20 otázkami, ktorý vyplníte online v tejto aplikácii. Úspešný je účastník s najmenej 15 správnymi odpoveďami (75 %). Kto nevyhovie, opakuje test v náhradnom termíne a dovtedy nesmie samostatne vykonávať prácu, na ktorú sa oboznámenie vzťahuje.</p></li><li><p>Úspešní účastníci dostanú doklad „Záznam o oboznámení zamestnanca“.</p></li></ul>$lq$);
insert into lq_tpl_topics values (2, $lq$Zákonník práce: BOZP a pracovné podmienky$lq$, 25, 15, $lq$<p>Rozsah: A 25 minút, B 15 minút. Cieľ: účastník pozná svoje základné povinnosti, pravidlá pracovného času a zodpovednosť za škodu.</p><p>2.1 Zamestnávateľ, zamestnanec, zástupcovia zamestnancov</p><p>Zákonník práce (zákon č. 311/2001 Z. z.) upravuje pracovnoprávne vzťahy medzi zamestnávateľom a zamestnancom. Zamestnancom je fyzická osoba, ktorá vykonáva závislú prácu pre zamestnávateľa. Záujmy zamestnancov môžu zastupovať odborová organizácia, zamestnanecká rada alebo zamestnanecký dôverník (§ 11a). V oblasti BOZP má osobitné postavenie zástupca zamestnancov pre bezpečnosť (téma 3).</p><p>2.2 Základné povinnosti zamestnancov a vedúcich zamestnancov</p><p><strong>Zamestnanec (§ 81)</strong> je povinný najmä:</p><ul><li><p>pracovať svedomito a riadne podľa svojich síl, znalostí a schopností, plniť pokyny nadriadených v súlade s právnymi predpismi,</p></li><li><p>dodržiavať pracovný čas a pracovnú disciplínu,</p></li><li><p>dodržiavať právne predpisy a ostatné predpisy vzťahujúce sa na vykonávanú prácu, najmä predpisy na zaistenie BOZP, s ktorými bol riadne oboznámený,</p></li><li><p>riadne hospodáriť s prostriedkami zverenými zamestnávateľom a chrániť jeho majetok pred poškodením, stratou, zničením a zneužitím.</p></li></ul><p><strong>Vedúci zamestnanec (§ 82)</strong> je okrem toho povinný najmä riadiť a kontrolovať prácu podriadených, utvárať priaznivé pracovné podmienky a zabezpečovať bezpečnosť a ochranu zdravia pri práci, zabezpečovať dodržiavanie právnych predpisov a ostatných predpisov a prijímať opatrenia na ochranu majetku zamestnávateľa.</p><p>Zamestnanec môže vykonávať aj inú zárobkovú činnosť, ak nie je v konkurenčnom vzťahu k zamestnávateľovi (§ 83). Konkrétne pravidlá organizácie upravuje pracovný poriadok (§ 84).</p><p>2.3 Pracovný čas a doba odpočinku</p><ul><li><p>Ustanovený týždenný pracovný čas je najviac 40 hodín. Priemerný týždenný pracovný čas vrátane práce nadčas nesmie presiahnuť 48 hodín.</p></li><li><p>Prestávka na odpočinok a jedenie: po šiestich hodinách nepretržitej práce najmenej 30 minút, u mladistvého po štyroch a pol hodinách najmenej 30 minút.</p></li><li><p>Nepretržitý denný odpočinok medzi koncom jednej a začiatkom ďalšej zmeny je najmenej 12 hodín, u mladistvého najmenej 14 hodín.</p></li><li><p>Prestávky a odpočinok slúžia aj prevencii úrazov – únava je častou príčinou chýb a úrazov.</p></li></ul><p>2.4 Ochrana práce (§ 146 – 151)</p><p>Zamestnávateľ je povinný sústavne zaisťovať bezpečnosť a ochranu zdravia zamestnancov pri práci, vytvárať bezpečné pracovné podmienky a oboznamovať zamestnancov s predpismi. Zamestnanci sú povinní dbať o svoju bezpečnosť a zdravie a o bezpečnosť a zdravie osôb, ktorých sa ich konanie týka. Dodržiavanie predpisov kontrolujú odborové orgány (§ 149) a inšpekcia práce (§ 150).</p><p>2.5 Ženy, mladiství a zamestnanci starajúci sa o deti</p><p>Tehotným ženám, matkám do konca deviateho mesiaca po pôrode a dojčiacim ženám sú zakázané práce uvedené v nariadení vlády č. 272/2004 Z. z.; mladistvým zamestnancom (do 18 rokov) práce uvedené v nariadení vlády č. 286/2004 Z. z. Mladiství nesmú pracovať nadčas, v noci ani mať pracovnú pohotovosť a pred prijatím musia byť lekársky vyšetrení. <mark>Zakázané práce a pracoviská u objednávateľa: ...</mark></p><p>2.6 Zodpovednosť za škodu</p><ul><li><p><strong>Zamestnanec</strong> zodpovedá za škodu, ktorú zamestnávateľovi spôsobil zavineným porušením povinností (§ 179). Pri nedbanlivosti je náhrada obmedzená – spravidla najviac štvornásobkom jeho priemerného mesačného zárobku (§ 186).</p></li><li><p>Zamestnanec je povinný upozorniť na hroziacu škodu a podľa možností jej zabrániť (§ 177 – 178).</p></li><li><p><strong>Zamestnávateľ</strong> zodpovedá za škodu pri pracovnom úraze a chorobe z povolania bez ohľadu na zavinenie (§ 195). Zodpovednosti sa môže celkom alebo čiastočne zbaviť najmä vtedy, ak zamestnanec porušil predpisy BOZP, s ktorými bol <strong>riadne oboznámený</strong> a ktorých dodržiavanie sa sústavne vyžadovalo a kontrolovalo, alebo ak bol pod vplyvom alkoholu či návykových látok (§ 196).</p></li></ul><p>Preto je dôležité, aby oboznámenie bolo preukázateľné a aby zamestnanec predpisy skutočne dodržiaval. Náhrady pri pracovnom úraze sa dnes poskytujú najmä z úrazového poistenia (téma 7).</p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Dodržiavať predpisy BOZP je základná povinnosť každého zamestnanca, vedúci za BOZP zodpovedá.</p></li><li><p>Po 6 hodinách práce patrí prestávka najmenej 30 minút, medzi zmenami odpočinok najmenej 12 hodín.</p></li><li><p>Porušenie predpisov, s ktorými bol zamestnanec oboznámený, môže znížiť jeho nároky pri úraze.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (3, $lq$Zákon č. 124/2006 Z. z. o bezpečnosti a ochrane zdravia pri práci$lq$, 60, 35, $lq$<p>Rozsah: A 60 minút, B 35 minút. Cieľ: účastník pozná povinnosti zamestnávateľa a svoje práva a povinnosti, vie, ako postupovať pri ohrození a pracovnom úraze.</p><p>3.1 Základné pojmy (§ 3)</p><table><thead><tr><th><strong>Pojem</strong></th><th><strong>Význam</strong></th></tr><tr><th>Nebezpečenstvo</th><th>vlastnosť alebo schopnosť niečoho (stroja, látky, postupu) spôsobiť poškodenie zdravia</th></tr><tr><th>Ohrozenie</th><th>situácia, v ktorej nemožno vylúčiť, že dôjde k poškodeniu zdravia</th></tr><tr><th>Riziko</th><th>pravdepodobnosť vzniku poškodenia zdravia a jeho možný rozsah</th></tr><tr><th>Pracovný prostriedok</th><th>stroj, prístroj, náradie, zariadenie alebo iný prostriedok používaný pri práci</th></tr><tr><th>Pracovisko</th><th>priestor, v ktorom zamestnanec pracuje alebo do ktorého má prístup pri práci</th></tr></thead><tbody></tbody></table><p>3.2 Všeobecné zásady prevencie (§ 5)</p><p>Prevencia má poradie: najprv riziku <strong>predchádzať</strong>, potom ho <strong>vyhodnotiť</strong>, odstraňovať nebezpečenstvá <strong>pri zdroji</strong>, prispôsobovať prácu človeku, nahrádzať nebezpečné bezpečným, uprednostniť <strong>kolektívne</strong> ochranné opatrenia pred individuálnymi (OOPP) a dávať zamestnancom vhodné pokyny.</p><p>3.3 Povinnosti zamestnávateľa (§ 6 – 10)</p><ul><li><p>posudzovať riziko a vypracovať písomný dokument o posúdení rizika, prijímať opatrenia na jeho zníženie,</p></li><li><p>zabezpečiť bezpečné pracovisko, pracovné prostriedky a pracovné postupy, poskytovať osobné ochranné pracovné prostriedky,</p></li><li><p>zabezpečiť prvú pomoc, protipožiarne opatrenia a evakuáciu, určiť zamestnancov, ktorí ich vykonávajú,</p></li><li><p>oboznamovať zamestnancov pravidelne, zrozumiteľne a preukázateľne (§ 7) – pri prijatí, preradení, zmene pracovných podmienok, novej technológii a <strong>opakovane najmenej raz za tri roky</strong>, ak predpisy neurčujú kratšiu lehotu; oboznamovanie sa vykonáva v pracovnom čase,</p></li><li><p>pri bezprostrednom a vážnom ohrození života alebo zdravia zabezpečiť zastavenie práce a odchod zamestnancov do bezpečia (§ 8),</p></li><li><p>kontrolovať dodržiavanie predpisov (§ 9) a spolupracovať so zamestnancami a ich zástupcami (§ 10).</p></li></ul><p>3.4 Práva a povinnosti zamestnancov (§ 12)</p><p><strong>Zamestnanec má právo</strong> najmä na bezpečnú prácu, na informácie o rizikách, na oboznámenie, na OOPP a má právo <strong>odmietnuť prácu alebo opustiť pracovisko</strong>, ak dôvodne usudzuje, že bezprostredne a vážne ohrozuje jeho život alebo zdravie či život a zdravie iných – takýto postup nemožno posudzovať ako nesplnenie povinnosti.</p><p><strong>Zamestnanec je povinný</strong> najmä:</p><ul><li><p>dodržiavať predpisy BOZP, pokyny a bezpečné pracovné postupy, s ktorými bol oboznámený,</p></li><li><p>používať pridelené OOPP a ochranné zariadenia, nepoškodzovať ich a neodstraňovať,</p></li><li><p>nepožívať alkohol a iné návykové látky na pracovisku a nenastupovať pod ich vplyvom do práce; podrobiť sa skúške na ich prítomnosť,</p></li><li><p>oznamovať nadriadenému nedostatky a chyby, ktoré by mohli ohroziť bezpečnosť, a podľa možností sa podieľať na ich odstraňovaní,</p></li><li><p>bezodkladne oznámiť pracovný úraz, ak mu to zdravotný stav dovoľuje, a spolupracovať pri jeho vyšetrovaní,</p></li><li><p>podrobiť sa lekárskym preventívnym prehliadkam, ak to vyžaduje predpis.</p></li></ul><p>3.5 Technické zariadenia a odborná spôsobilosť (§ 13 – 16)</p><p>Pracovné prostriedky a technické zariadenia musia byť bezpečné a pravidelne kontrolované. Určité pracovné prostriedky a vyhradené technické zariadenia smie obsluhovať alebo na nich pracovať iba osoba s platným <strong>preukazom, osvedčením alebo dokladom</strong> (§ 16) – napríklad vodiči motorových vozíkov, žeriavnici, viazači bremien, kuriči či elektrotechnici (téma 6).</p><p>3.6 Pracovný úraz, choroba z povolania, nebezpečná udalosť (§ 17)</p><ul><li><p><strong>Pracovný úraz</strong> je poškodenie zdravia, ktoré zamestnanec utrpel pri plnení pracovných úloh alebo v priamej súvislosti s ním, nezávisle od jeho vôle, krátkodobým, náhlym a násilným pôsobením vonkajších vplyvov.</p></li><li><p><strong>Registrovaný pracovný úraz</strong> je úraz, ktorý spôsobil pracovnú neschopnosť dlhšiu ako tri dni alebo smrť; zamestnávateľ o ňom spisuje záznam.</p></li><li><p><strong>Závažný pracovný úraz</strong> (smrť alebo ťažká ujma na zdraví) zamestnávateľ bezodkladne ohlasuje inšpektorátu práce a policajnému zboru.</p></li><li><p><strong>Nebezpečná udalosť</strong> je udalosť, pri ktorej nedošlo k úrazu, ale mohlo; aj tú treba oznámiť a zaevidovať, aby sa predišlo úrazu nabudúce.</p></li></ul><p><strong>Postup zamestnanca pri úraze:</strong> poskytnúť prvú pomoc a privolať pomoc (112, 155), zabezpečiť miesto, aby sa úraz neopakoval, a nemeniť ho, ak to nie je nutné, oznámiť úraz nadriadenému, uviesť svedkov. <mark>Kontakt na zodpovednú osobu u objednávateľa: ...</mark></p><p>3.7 Organizácia BOZP u zamestnávateľa (§ 18 – 23, 27)</p><ul><li><p><strong>Zástupca zamestnancov pre bezpečnosť</strong> – zamestnávateľ s najmenej 10 zamestnancami ho musí mať; jeden zástupca pripadá na najviac 50 zamestnancov v rizikovejších odvetviach, inak na najviac 100.</p></li><li><p><strong>Komisia BOZP</strong> – zriaďuje ju zamestnávateľ s viac ako 100 zamestnancami, zasadá najmenej raz ročne.</p></li><li><p><strong>Bezpečnostnotechnická služba</strong> – zabezpečuje ju bezpečnostný technik (vlastný alebo dodávateľsky).</p></li><li><p><strong>Spolupráca zamestnávateľov</strong> na spoločnom pracovisku – písomná dohoda o koordinácii BOZP (§ 18).</p></li><li><p><strong>Výchova a vzdelávanie</strong> – oboznamovanie môže vykonať zamestnávateľ sám alebo osoba s oprávnením NIP (§ 7 ods. 4, § 27), ako je Keylo s.r.o.</p></li></ul><p>Príloha č. 1 zákona obsahuje zoznam činností s vyšším rizikom (napr. stavebníctvo, výroba, doprava), pri ktorých sú prísnejšie požiadavky.</p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Riziko je pravdepodobnosť a rozsah možného poškodenia zdravia – vždy ho najprv odstraňujeme pri zdroji.</p></li><li><p>Pri bezprostrednom a vážnom ohrození máte právo odmietnuť prácu alebo opustiť pracovisko.</p></li><li><p>Každý úraz a nebezpečnú udalosť ihneď oznámte nadriadenému.</p></li><li><p>Alkohol a drogy na pracovisku sú zakázané, skúške sa treba podrobiť.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (4, $lq$Zákon č. 125/2006 Z. z. o inšpekcii práce$lq$, 15, 10, $lq$<p>Rozsah: A 15 minút, B 10 minút. Cieľ: účastník vie, kto dozerá na BOZP a aké má inšpektor oprávnenia.</p><p>Inšpekcia práce dozerá na dodržiavanie pracovnoprávnych predpisov a predpisov BOZP. Orgánmi štátnej správy sú ministerstvo práce, <strong>Národný inšpektorát práce</strong> (riadi inšpektoráty, vydáva oprávnenia a osvedčenia) a <strong>inšpektoráty práce</strong> v krajoch. <mark>Príslušný inšpektorát práce pre objednávateľa: ...</mark></p><p><strong>Inšpektor práce</strong> smie najmä vstupovať na pracoviská a do priestorov zamestnávateľa, vyžadovať doklady a vysvetlenia, odoberať vzorky, nariadiť odstránenie nedostatkov, zakázať používanie nebezpečných pracovných prostriedkov a prerušiť prácu pri bezprostrednom ohrození. O výsledku vyhotoví protokol.</p><p>Zamestnávateľ aj zamestnanci sú povinní inšpektorovi umožniť výkon inšpekcie a poskytnúť súčinnosť (§ 16). Za porušenie predpisov môže inšpektorát uložiť zamestnávateľovi pokutu ako správny delikt (§ 19) a za marenie inšpekcie poriadkovú pokutu (§ 20). Zákon o nelegálnej práci a nelegálnom zamestnávaní (č. 82/2005 Z. z.) zakazuje prácu bez riadneho pracovnoprávneho vzťahu a jej kontrolu tiež vykonáva inšpekcia práce.</p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Na BOZP dozerá inšpektorát práce, oprávnenia vydáva Národný inšpektorát práce.</p></li><li><p>Inšpektorovi treba umožniť vstup a poskytnúť súčinnosť.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (5, $lq$Zákon č. 355/2007 Z. z. o ochrane, podpore a rozvoji verejného zdravia$lq$, 15, 10, $lq$<p>Rozsah: A 15 minút, B 10 minút. Cieľ: účastník pozná kategorizáciu prác, rizikové práce a úlohu pracovnej zdravotnej služby.</p><p>Zákon chráni zdravie pri práci pred faktormi pracovného prostredia, ako sú hluk, vibrácie, prach, chemické a biologické faktory, záťaž teplom a chladom, fyzická a psychická záťaž. Dozor vykonávajú <strong>regionálne úrady verejného zdravotníctva (RÚVZ)</strong> a Úrad verejného zdravotníctva SR.</p><p>5.1 Kategorizácia prác (§ 31)</p><table><thead><tr><th><strong>Kategória</strong></th><th><strong>Charakteristika</strong></th></tr><tr><th>1</th><th>práca bez zdravotného rizika</th></tr><tr><th>2</th><th>práca, pri ktorej sa neočakáva nepriaznivý vplyv na zdravie (expozícia pod limitmi)</th></tr><tr><th>3</th><th>riziková práca – expozícia nad limitmi alebo práca s vyšším rizikom, vyžaduje ochranné opatrenia a lekárske preventívne prehliadky</th></tr><tr><th>4</th><th>riziková práca s vysokým rizikom – expozíciu nemožno znížiť pod limity ani technickými opatreniami, nevyhnutné sú OOPP a ďalšie ochranné opatrenia</th></tr></thead><tbody></tbody></table><p>Rizikové práce (kategória 3 a 4) vyhlasuje rozhodnutím RÚVZ. Zamestnávateľ musí pri nich zabezpečiť najmä ochranné opatrenia, OOPP, prevádzkový poriadok a lekárske preventívne prehliadky vo vzťahu k práci. <mark>Rizikové práce u objednávateľa: ...</mark></p><p>5.2 Pracovná zdravotná služba (§ 30a a nasl.)</p><p>Každý zamestnávateľ je povinný zabezpečiť pracovnú zdravotnú službu – tím odborníkov (lekár, verejný zdravotník a ďalší), ktorý posudzuje zdravotné riziká, kategorizuje práce, dohliada na zdravie zamestnancov a radí zamestnávateľovi. Zamestnanec je povinný podrobiť sa lekárskym prehliadkam, ktoré zamestnávateľ podľa zákona nariadi.</p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Práce sa zaraďujú do kategórií 1 až 4, kategórie 3 a 4 sú rizikové práce.</p></li><li><p>Pri rizikových prácach sú povinné ochranné opatrenia a lekárske prehliadky.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (6, $lq$Bezpečnosť technických zariadení$lq$, 15, 10, $lq$<p>Rozsah: A 15 minút, B 10 minút. Cieľ: účastník rozumie, čo sú vyhradené technické zariadenia, kto na nich smie pracovať a ako sa chrániť pred úrazom elektrinou.</p><p>Vyhláška č. 508/2009 Z. z. rozdeľuje technické zariadenia <strong>tlakové, zdvíhacie, elektrické a plynové</strong> a určuje, ktoré z nich sú <strong>vyhradené technické zariadenia (VTZ)</strong>. Podľa miery ohrozenia sa delia do <strong>skupín A, B a C</strong> (skupina A s najvyšším ohrozením) (§ 4). VTZ podliehajú pravidelným odborným prehliadkam, skúškam a revíziám.</p><p>6.1 Obsluha a práca na VTZ</p><p>Obsluhovať VTZ alebo na nich pracovať smie iba osoba s príslušnou odbornou spôsobilosťou a dokladom (§ 16 zákona č. 124/2006 Z. z., § 17 vyhlášky). Zamestnanec bez dokladu <strong>nesmie</strong> takéto zariadenie obsluhovať, opravovať ani do neho zasahovať – ani „len na chvíľu“.</p><p>6.2 Odborná spôsobilosť na elektrických zariadeniach</p><table><thead><tr><th><strong>Kvalifikácia (vyhláška č. 508/2009 Z. z.)</strong></th><th><strong>Zjednodušene</strong></th></tr><tr><th>Osoba bez elektrotechnickej kvalifikácie</th><th>smie elektrické zariadenia iba používať podľa návodu (zapnúť, vypnúť), nesmie do nich zasahovať</th></tr><tr><th>Poučená osoba (§ 20)</th><th>oboznámená zamestnávateľom s činnosťou na elektrických zariadeniach a upozornená na nebezpečenstvo; smie vykonávať určené jednoduché činnosti</th></tr><tr><th>Elektrotechnik (§ 21)</th><th>s elektrotechnickým vzdelaním, pracuje pod dozorom alebo podľa pokynov</th></tr><tr><th>Samostatný elektrotechnik (§ 22)</th><th>samostatne vykonáva činnosť na elektrických zariadeniach</th></tr><tr><th>Elektrotechnik na riadenie činnosti (§ 23)</th><th>riadi činnosť alebo prevádzku elektrických zariadení</th></tr><tr><th>Revízny technik (§ 24)</th><th>vykonáva odborné prehliadky a skúšky (revízie)</th></tr></thead><tbody></tbody></table><p>6.3 Zásady bezpečnosti pri elektrických zariadeniach</p><ul><li><p>pred použitím skontrolovať, či nie je poškodený prívod, vidlica alebo kryt; poškodené zariadenie nepoužívať a nahlásiť,</p></li><li><p>neodstraňovať kryty, neopravovať zariadenia svojpomocne, nepreťažovať zásuvky a predlžovacie prívody,</p></li><li><p>ručné náradie a spotrebiče musia mať platnú revíziu alebo kontrolu, <mark>u objednávateľa označené štítkom s dátumom</mark>,</p></li><li><p>pri úraze elektrinou najprv <strong>bezpečne prerušiť prúd</strong> (vypnúť istič, vytiahnuť vidlicu) a až potom sa postihnutého dotknúť; zavolať 155 alebo 112, pri zastavení dýchania začať resuscitáciu.</p></li></ul><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Zariadenie, na ktoré nemáte doklad alebo kvalifikáciu, neobsluhujte ani neopravujte.</p></li><li><p>Poškodené elektrické zariadenie hneď vyraďte a nahláste.</p></li><li><p>Pri úraze elektrinou najprv vypnúť prúd, potom pomáhať.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (7, $lq$Úrazové poistenie a náhrada príjmu pri pracovnej neschopnosti$lq$, 10, 5, $lq$<p>Rozsah: A 10 minút, B 5 minút. Cieľ: účastník vie, na aké dávky má nárok pri pracovnom úraze a chorobe z povolania.</p><p>Podľa zákona č. 461/2003 Z. z. o sociálnom poistení je každý zamestnanec <strong>úrazovo poistený</strong> – poistné platí zamestnávateľ. Dávky vypláca Sociálna poisťovňa. Pri pracovnom úraze alebo chorobe z povolania môže poškodenému patriť najmä:</p><ul><li><p>úrazový príplatok (počas pracovnej neschopnosti),</p></li><li><p>úrazová renta a jednorazové vyrovnanie (pri trvalom poklese pracovnej schopnosti),</p></li><li><p>náhrada za bolesť a náhrada za sťaženie spoločenského uplatnenia,</p></li><li><p>náhrada nákladov spojených s liečením,</p></li><li><p>pracovná rehabilitácia, rehabilitačné a rekvalifikácia,</p></li><li><p>pri smrti pozostalostná úrazová renta, jednorazové odškodnenie a náhrada nákladov spojených s pohrebom.</p></li></ul><p>Podľa zákona č. 462/2003 Z. z. platí zamestnávateľ zamestnancovi počas prvých 10 dní dočasnej pracovnej neschopnosti <strong>náhradu príjmu</strong>: za 1. až 3. deň 25 % a za 4. až 10. deň 55 % denného vymeriavacieho základu. Od 11. dňa vypláca nemocenské Sociálna poisťovňa.</p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>Úrazovo poistený je každý zamestnanec, poistné platí zamestnávateľ.</p></li><li><p>Úraz treba nahlásiť ihneď – bez záznamu o úraze sa nároky ťažko uplatňujú.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (8, $lq$Vyhláška č. 59/1982 Zb. – základné požiadavky na bezpečnosť práce$lq$, 15, 10, $lq$<p>Rozsah: A 15 minút, B 10 minút. Cieľ: účastník pozná všeobecné bezpečnostné pravidlá na pracovisku.</p><p>Vyhláška je staršia, no formálne platná. Kde ju upravujú novšie nariadenia vlády (téma 9), postupuje sa podľa nich. Školiteľ vyberie časti podľa práce účastníkov:</p><ul><li><p><strong>pracoviská a komunikácie</strong> – udržiavať poriadok, voľné únikové cesty a prístup k hasiacim prístrojom, nepoužívať poškodené rebríky, zabezpečiť otvory a okraje pred pádom,</p></li><li><p><strong>stroje a zariadenia</strong> – používať iba s funkčnými krytmi a ochrannými zariadeniami, opravy a čistenie vykonávať len na zastavenom a zaistenom stroji,</p></li><li><p><strong>náradie a pracovné pomôcky</strong> – iba nepoškodené a určené na daný účel,</p></li><li><p><strong>manipulácia s materiálom a skladovanie</strong> – stabilné ukladanie, dodržiavanie nosnosti regálov a dovolenej výšky stohov,</p></li><li><p><strong>elektrické a tlakové zariadenia</strong> – pozri tému 6. <mark>Doplniť podľa činnosti objednávateľa.</mark></p></li></ul>$lq$);
insert into lq_tpl_topics values (9, $lq$Nariadenia vlády a osobitné predpisy podľa druhu práce$lq$, 45, 35, $lq$<p>Rozsah: A 45 minút, B 35 minút. Cieľ: účastník pozná požiadavky, ktoré sa týkajú jeho pracoviska a práce.</p><p>Školiteľ vyberie predpisy podľa práce účastníkov. <mark>Výber pre objednávateľa: ...</mark></p><p>9.1 Pracovisko (NV č. 391/2006 Z. z.)</p><p>Pracovisko musí byť bezpečné, primerane osvetlené, vetrané a vykurované, s bezpečnými podlahami, komunikáciami a únikovými cestami, s hygienickými zariadeniami a s vybavením na poskytnutie prvej pomoci. Požiadavky na osvetlenie upravuje vyhláška č. 541/2007 Z. z.</p><p>9.2 Pracovné prostriedky (NV č. 392/2006 Z. z.)</p><p>Pracovné prostriedky musia byť vhodné na danú prácu, pravidelne kontrolované a udržiavané; ovládače musia byť zreteľné, stroje musia mať zastavovacie zariadenie a ochranné kryty. Zamestnanec ich smie používať až po oboznámení s návodom.</p><p>9.3 Osobné ochranné pracovné prostriedky (NV č. 395/2006 Z. z.)</p><p>OOPP sú poslednou ochranou, keď riziko nemožno odstrániť inak. Zamestnávateľ ich poskytuje <strong>bezplatne</strong> podľa vlastného zoznamu OOPP, udržiava ich v použiteľnom stave a kontroluje ich používanie. Zamestnanec ich je povinný <strong>používať</strong>, starať sa o ne a hlásiť ich poškodenie. <mark>Prehľad OOPP pre pracovné pozície objednávateľa: ...</mark></p><p>9.4 Bezpečnostné značky (NV č. 387/2006 Z. z.)</p><table><thead><tr><th><strong>Farba</strong></th><th><strong>Význam</strong></th><th><strong>Príklad</strong></th></tr><tr><th>Červená</th><th>zákaz; protipožiarne vybavenie</th><th>Zákaz fajčenia, hasiaci prístroj</th></tr><tr><th>Žltá</th><th>výstraha</th><th>Pozor, elektrické napätie</th></tr><tr><th>Modrá</th><th>príkaz</th><th>Používaj ochranné okuliare</th></tr><tr><th>Zelená</th><th>bezpečie, záchrana</th><th>Úniková cesta, prvá pomoc</th></tr></thead><tbody></tbody></table><p>9.5 Ručná manipulácia s bremenami (NV č. 281/2006 Z. z.)</p><p>Bremená zdvíhať s rovným chrbtom, z podrepu, blízko pri tele, bez prudkých pohybov a rotácie trupu; ťažké a objemné bremená prenášať vo dvojici alebo s pomôckami. Prípustná hmotnosť bremena závisí od pohlavia, veku, frekvencie a polohy pri práci – zamestnávateľ ju má posúdenú v hodnotení rizika.</p><p>9.6 Práca so zobrazovacími jednotkami (NV č. 276/2006 Z. z.)</p><p>Správne nastavená obrazovka (horný okraj vo výške očí), stolička a osvetlenie bez odleskov, pravidelné prestávky alebo zmena činnosti; zamestnanec má nárok na vyšetrenie zraku.</p><p>9.7 Hluk a chemické faktory (NV č. 115/2006 a 355/2006 Z. z.)</p><p>Pri hluku nad dolnou akčnou hodnotou (80 dB(A)) zamestnávateľ poskytuje chrániče sluchu, nad hornou akčnou hodnotou (85 dB(A)) je ich používanie povinné; limitná hodnota expozície je 87 dB(A). Pri práci s chemickými látkami dodržiavať karty bezpečnostných údajov, označenie obalov, používať OOPP a nejesť a nepiť na pracovisku.</p><p>9.8 Doprava a vozidlá (vyhláška č. 208/1991 Zb., zákon č. 462/2007 Z. z.)</p><p>Pri práci s vozidlami: kontrola technického stavu pred jazdou, zaistenie vozidla pri oprave, dodržiavanie pracovného času a odpočinku vodičov. <mark>Iba ak sa týka objednávateľa.</mark></p><table><tbody><tr><td><p><strong>Zapamätajte si</strong></p><ul><li><p>OOPP dostávate zadarmo a ste povinní ich používať.</p></li><li><p>Farby značiek: červená zákaz, žltá výstraha, modrá príkaz, zelená bezpečie.</p></li><li><p>Bremená dvíhajte z podrepu s rovným chrbtom, ťažké vo dvojici alebo s pomôckou.</p></li></ul></td></tr></tbody></table>$lq$);
insert into lq_tpl_topics values (10, $lq$Vnútorné predpisy a riziká pracoviska objednávateľa$lq$, 35, 30, $lq$<p>Rozsah: A 35 minút, B 30 minút. Cieľ: účastník pozná konkrétne riziká svojho pracoviska, opatrenia a postupy u zamestnávateľa.</p><p>Táto téma sa pripravuje pre každého objednávateľa zvlášť z jeho dokumentácie BOZP. Ak sa vykonáva formou e-learningu, modul musí byť pripravený pre konkrétneho objednávateľa (časť 3.2 projektu).</p><table><thead><tr><th><strong>Oblasť</strong></th><th><strong>Obsah (doplniť podľa objednávateľa)</strong></th></tr><tr><th>Vnútorné predpisy BOZP</th><th><mark>smernica BOZP, pracovný poriadok, zákaz alkoholu a fajčenia, pravidlá pohybu po areáli</mark></th></tr><tr><th>Hodnotenie rizík</th><th><mark>hlavné nebezpečenstvá a ohrozenia pre jednotlivé pracoviská a pozície, výsledky hodnotenia rizík</mark></th></tr><tr><th>Opatrenia</th><th><mark>technické a organizačné opatrenia, zakázané činnosti a priestory</mark></th></tr><tr><th>OOPP</th><th><mark>zoznam OOPP pre pozície, výdaj a výmena</mark></th></tr><tr><th>Návody a pracovné postupy</th><th><mark>stroje a zariadenia, ktoré zamestnanci obsluhujú, bezpečné pracovné postupy</mark></th></tr><tr><th>Prvá pomoc</th><th><mark>umiestnenie lekárničiek, osoby určené na prvú pomoc</mark>; tiesňové čísla 112, 155 (záchranná služba), 150 (hasiči), 158 (polícia)</th></tr><tr><th>Mimoriadne situácie</th><th><mark>evakuačný plán, zhromaždisko, postup pri požiari a havárii</mark></th></tr><tr><th>Pracovný úraz</th><th><mark>komu hlásiť, kniha úrazov, kontaktná osoba</mark></th></tr><tr><th>Technické normy</th><th><mark>STN podľa druhu práce</mark></th></tr></thead><tbody></tbody></table>$lq$);
insert into lq_tpl_topics values (11, $lq$Poznatky z pracovnej úrazovosti a chorôb z povolania (opakované oboznamovanie)$lq$, 0, 15, $lq$<p>Rozsah: B 15 minút. Cieľ: účastník sa poučí z konkrétnych úrazov a vie, ako im predchádzať.</p><p>Rozbor sa robí na skutočných prípadoch u objednávateľa a v odvetví. Pri každom prípade sa preberá: čo sa stalo, príčina (technická, organizačná, ľudský faktor), ktoré pravidlo bolo porušené a aké opatrenie by úrazu zabránilo.</p><p><strong>Najčastejšie príčiny pracovných úrazov:</strong></p><ul><li><p>pošmyknutie, zakopnutie a pád na rovine (mokré podlahy, neporiadok, nevhodná obuv),</p></li><li><p>pád z výšky (rebríky, lešenia, okraje, otvory),</p></li><li><p>manipulácia s bremenami a materiálom,</p></li><li><p>zachytenie alebo stlačenie strojom (odstránený kryt, práca na bežiacom stroji),</p></li><li><p>doprava v areáli a na cestách,</p></li><li><p>úraz elektrickým prúdom,</p></li><li><p>nepoužívanie OOPP, únava, zhon a alkohol.</p></li></ul><p><mark>Úrazy a nebezpečné udalosti u objednávateľa od posledného oboznámenia: ...</mark></p><p><mark>Aktuálne údaje o pracovnej úrazovosti v SR – Správa o stave ochrany práce (Národný inšpektorát práce), posledný dostupný rok: ...</mark></p><p><strong>Choroby z povolania</strong> vznikajú dlhodobým pôsobením faktorov práce (napr. hluk, vibrácie, preťažovanie končatín, prach, chemické látky). Prevencia: dodržiavať opatrenia z kategorizácie prác, používať OOPP a chodiť na lekárske prehliadky.</p>$lq$);
insert into lq_tpl_questions (slot, topic_no, variant, text, options, correct) values
(1, 2, 1, $lq$Mladistvému zamestnancovi patrí prestávka na odpočinok a jedenie najmenej 30 minút po:$lq$, $lq$["4,5 hodinách nepretržitej práce", "8 hodinách nepretržitej práce", "6 hodinách nepretržitej práce"]$lq$::jsonb, 0),
(2, 3, 1, $lq$Riziko je podľa zákona o BOZP:$lq$, $lq$["pravdepodobnosť vzniku poškodenia zdravia a jeho možný rozsah", "vlastnosť stroja spôsobiť úraz", "každá práca vo výške"]$lq$::jsonb, 0),
(3, 4, 1, $lq$Dozor nad dodržiavaním predpisov BOZP vykonáva:$lq$, $lq$["obecný úrad", "daňový úrad", "inšpektorát práce"]$lq$::jsonb, 2),
(4, 5, 1, $lq$Pracovnú zdravotnú službu je povinný zabezpečiť:$lq$, $lq$["iba zamestnávateľ s viac ako 50 zamestnancami", "každý zamestnávateľ", "iba zamestnávateľ s prácami kategórie 4"]$lq$::jsonb, 1),
(5, 6, 1, $lq$Osoba bez elektrotechnickej kvalifikácie smie elektrické zariadenie:$lq$, $lq$["iba používať podľa návodu", "opravovať, ak je vypnuté", "otvárať a odstraňovať kryty"]$lq$::jsonb, 0),
(6, null, 1, $lq$Proti chorobám z povolania chráni zamestnanca najmä:$lq$, $lq$["dodržiavanie opatrení, používanie OOPP a lekárske prehliadky", "vynechávanie prestávok", "práca nadčas"]$lq$::jsonb, 0),
(7, null, 1, $lq$Pri práci so zobrazovacou jednotkou má byť horný okraj obrazovky:$lq$, $lq$["približne vo výške očí", "pod úrovňou stola", "výrazne nad úrovňou očí"]$lq$::jsonb, 0),
(8, null, 1, $lq$Bremeno sa správne dvíha:$lq$, $lq$["rýchlo s otočením trupu", "z podrepu s rovným chrbtom, blízko pri tele", "s ohnutým chrbtom a vystretými nohami"]$lq$::jsonb, 1),
(9, null, 1, $lq$Pri ukladaní materiálu do regálov treba:$lq$, $lq$["ťažké predmety ukladať navrch", "dodržiavať nosnosť regálu a ukladať stabilne", "ukladať čo najvyššie bez ohľadu na nosnosť"]$lq$::jsonb, 1),
(10, null, 1, $lq$Na úspešné overenie vedomostí písomným testom je potrebných najmenej:$lq$, $lq$["100 % správnych odpovedí", "75 % správnych odpovedí", "50 % správnych odpovedí"]$lq$::jsonb, 1),
(11, null, 1, $lq$Únikové cesty a prístup k hasiacim prístrojom musia byť:$lq$, $lq$["stále voľné", "voľné iba počas kontroly", "môžu byť dočasne zastavané materiálom"]$lq$::jsonb, 0),
